package android.content;import java.util.*;public class SharedPreferences {private final Map<String,Object> data=new HashMap<>();public boolean getBoolean(String key,boolean fallback){Object x=data.get(key);return x instanceof Boolean?(Boolean)x:fallback;}@SuppressWarnings("unchecked")public Set<String> getStringSet(String key,Set<String> fallback){Object x=data.get(key);return x instanceof Set?new HashSet<>((Set<String>)x):fallback;}public Editor edit(){return new Editor();}public class Editor{public Editor putBoolean(String k,boolean v){data.put(k,v);return this;}public Editor putStringSet(String k,Set<String> v){data.put(k,new HashSet<>(v));return this;}public void apply(){}}}
